static lv_color_t getBarColor(int h)
{
    float t = (float)h / SCREEN_HEIGHT;
    t = LV_CLAMP(0.0f, t, 1.0f);

    const uint8_t r = (uint8_t)(68 + 143 * t);
    const uint8_t g = (uint8_t)(92 + 38 * t);
    const uint8_t b = (uint8_t)(118 - 38 * t);
    return lv_color_make(r, g, b);
}

