void ui_MusicScreen_drawAudioBandsCool(const float* bands) {
    if (!s_music_visual_host) {
        return;
    }

    const int hostWidth = lv_obj_get_content_width(s_music_visual_host);
    const int hostHeight = lv_obj_get_content_height(s_music_visual_host);
    const int visualMaxHeight = LV_MAX(8, (hostHeight * 9) / 10);
    const int columnWidth = LV_MAX(1, hostWidth / BAND_COUNT);
    const int leftPadding = LV_MAX(0, (hostWidth - (columnWidth * BAND_COUNT)) / 2);
    const int railWidth = LV_MAX(1, columnWidth - 10);
    const int barWidth = LV_MAX(1, railWidth);
    const int barOffset = (columnWidth - barWidth) / 2;
    const int railOffset = (columnWidth - railWidth) / 2;

    if (!s_music_visual_ambience) {
        s_music_visual_ambience = lv_obj_create(s_music_visual_host);
        lv_obj_set_size(s_music_visual_ambience, hostWidth, hostHeight);
        lv_obj_align(s_music_visual_ambience, LV_ALIGN_BOTTOM_MID, 0, 0);
        lv_obj_clear_flag(s_music_visual_ambience, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_style_radius(s_music_visual_ambience, 0, 0);
        lv_obj_set_style_border_width(s_music_visual_ambience, 0, 0);
        lv_obj_set_style_pad_all(s_music_visual_ambience, 0, 0);
        lv_obj_set_style_bg_opa(s_music_visual_ambience, LV_OPA_TRANSP, 0);
        lv_obj_set_style_shadow_width(s_music_visual_ambience, 0, 0);
        lv_obj_set_style_shadow_opa(s_music_visual_ambience, LV_OPA_TRANSP, 0);
        lv_obj_move_background(s_music_visual_ambience);
    } else {
        lv_obj_set_size(s_music_visual_ambience, hostWidth, hostHeight);
        lv_obj_align(s_music_visual_ambience, LV_ALIGN_BOTTOM_MID, 0, 0);
    }

    for (int i = 0; i < BAND_COUNT; i++) {

        // bands: 0~255
        int boostedBand = (int)(bands[i] * 2.0f);
        if (boostedBand > 255) {
            boostedBand = 255;
        }
        if (boostedBand < 0) {
            boostedBand = 0;
        }
        barTargets[i] = lv_map(boostedBand, 0, 255, 3, visualMaxHeight);

        /* ---------- 下落拖尾平滑 ---------- */
        if (barTargets[i] < barHeights[i]) {
            barHeights[i] -= (barHeights[i] - barTargets[i]) / BAR_FALL_FACTOR;
        } else {
            barHeights[i] += (barTargets[i] - barHeights[i]) / 2;
        }

        if (barHeights[i] < 2) {
            barHeights[i] = 2;
        }

        if (!barRails[i]) {
            barRails[i] = lv_obj_create(s_music_visual_host);
            lv_obj_set_size(barRails[i], railWidth, hostHeight);
            lv_obj_clear_flag(barRails[i], LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_set_style_radius(barRails[i], 0, 0);
            lv_obj_set_style_bg_color(barRails[i], lv_color_hex(0x192028), 0);
            lv_obj_set_style_bg_opa(barRails[i], 42, 0);
            lv_obj_set_style_border_width(barRails[i], 1, 0);
            lv_obj_set_style_border_color(barRails[i], lv_color_hex(0x293545), 0);
            lv_obj_set_style_border_opa(barRails[i], 28, 0);
            lv_obj_set_style_pad_all(barRails[i], 0, 0);
            lv_obj_set_style_shadow_width(barRails[i], 0, 0);
        }

        lv_obj_align(barRails[i], LV_ALIGN_TOP_LEFT, leftPadding + i * columnWidth + railOffset, 0);

        /* ---------- 瀑布拖尾 ---------- */
        if (!bars[i]) {
            bars[i] = lv_obj_create(s_music_visual_host);
            lv_obj_set_style_radius(bars[i], 0, 0);
            lv_obj_set_width(bars[i], barWidth);
            lv_obj_clear_flag(bars[i], LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_set_style_border_width(bars[i], 0, 0);
            lv_obj_set_style_pad_all(bars[i], 0, 0);
            lv_obj_set_style_bg_grad_dir(bars[i], LV_GRAD_DIR_VER, 0);
            lv_obj_set_style_bg_main_stop(bars[i], 0, 0);
            lv_obj_set_style_bg_grad_stop(bars[i], 255, 0);
            lv_obj_set_style_shadow_width(bars[i], 3, 0);
            lv_obj_set_style_shadow_spread(bars[i], 0, 0);
        }

        lv_obj_set_height(bars[i], barHeights[i]);
        lv_obj_align(bars[i], LV_ALIGN_TOP_LEFT, leftPadding + i * columnWidth + barOffset, 0);
        lv_obj_set_style_bg_color(bars[i], getBarColor(barHeights[i]), 0);
        lv_obj_set_style_bg_grad_color(bars[i], lv_color_hex(0x0B1017), 0);
        lv_obj_set_style_bg_opa(bars[i], 170, 0);
        lv_obj_set_style_shadow_color(bars[i], getBarColor(barHeights[i]), 0);
        lv_obj_set_style_shadow_opa(bars[i], 28, 0);
        if (peaks[i]) {
            lv_obj_add_flag(peaks[i], LV_OBJ_FLAG_HIDDEN);
        }
    }
}



