// 绘制频谱条形图
void ui_MusicScreen_drawAudioBands(const float* bands) {
    if (!s_music_visual_host) {
        return;
    }

    // 计算每条柱子的宽度和间距
    const int hostWidth = lv_obj_get_content_width(s_music_visual_host);
    const int barWidth  = LV_MAX(1, hostWidth / BAND_COUNT);
    const int maxHeight = lv_obj_get_content_height(s_music_visual_host);
    const int leftPadding = LV_MAX(0, (hostWidth - (barWidth * BAND_COUNT)) / 2);

    for (int i = 0; i < BAND_COUNT; i++) {
        int barHeight = (int)((bands[i] / 255.0f) * maxHeight);

        if (!bars[i]) {
            // 第一次创建对象
            bars[i] = lv_obj_create(s_music_visual_host);
            lv_obj_set_size(bars[i], barWidth - 2, barHeight); // 留一点间隙
            lv_obj_set_style_bg_color(bars[i], lv_color_make(0, 255, 0), 0);
            lv_obj_set_style_radius(bars[i], 0, 0);
            lv_obj_set_style_border_width(bars[i], 0, 0);
            lv_obj_set_style_pad_all(bars[i], 0, 0);
            lv_obj_clear_flag(bars[i], LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_align(bars[i], LV_ALIGN_BOTTOM_LEFT, leftPadding + i * barWidth, 0);
        } else {
            // 更新高度
            lv_obj_set_height(bars[i], barHeight);
            lv_obj_align(bars[i], LV_ALIGN_BOTTOM_LEFT, leftPadding + i * barWidth, 0);
        }
    }
}


